(function () { 'use strict'; var COMMON = [ { sel: '.nav-links a[href="/"]', html: 'Benvinguts' }, { sel: '.nav-links a[href="/principiantes/"]', html: 'Principiants' }, { sel: '.nav-links a[href="/intermedios/"]', html: 'Intermedis' }, { sel: '.nav-links a[href="/avanzados/"]', html: 'Avançats' }, { sel: '.nav-links a[href="/cuerpo-al-texto/"]', html: 'Cos al text' }, { sel: '.nav-links a[href="/quienes-somos/"]', html: 'Nosaltres' }, { sel: '.nav-links a[href="/blog/"]', html: 'Lectures' }, { sel: '.nav-cta a', html: 'Escriu-nos' }, { sel: '.nav-has-dropdown > a', html: 'Fotos i vídeos <span class="nav-chevron">▾</span>' }, { sel: '.mobile-menu-nav a[href="/"]', html: 'Benvinguts' }, { sel: '.mobile-menu-nav a[href="/principiantes/"]', html: 'Principiants' }, { sel: '.mobile-menu-nav a[href="/intermedios/"]', html: 'Intermedis' }, { sel: '.mobile-menu-nav a[href="/avanzados/"]', html: 'Avançats' }, { sel: '.mobile-menu-nav a[href="/cuerpo-al-texto/"]', html: 'Cos al text' }, { sel: '.mobile-menu-nav a[href="/quienes-somos/"]', html: 'Nosaltres' }, { sel: '.mobile-menu-nav a[href="/blog/"]', html: 'Lectures' }, { sel: '.mm-cta', html: 'Escriu-nos →' }, { sel: '.btn-wa', html: 'Reservar classe <span class="arrow">→</span>' }, { sel: '.hamburger', attr: 'aria-label', val: 'Obrir menú' }, { sel: '.seo-footer-nav a[href="/principiantes/"]', html: 'Principiants' }, { sel: '.seo-footer-nav a[href="/intermedios/"]', html: 'Intermedis' }, { sel: '.seo-footer-nav a[href="/avanzados/"]', html: 'Avançats' }, { sel: '.seo-footer-nav a[href="/cuerpo-al-texto/"]', html: 'Cos al text' }, { sel: '.seo-footer-nav a[href="/quienes-somos/"]', html: 'Nosaltres' }, { sel: '.seo-footer-nav a[href="/contacto/"]', html: 'Contacte' }, { findText: '.seo-footer-copy', from: '© 2025 talleresdeteatro.es · Gràcia, Barcelona', to: '© 2025 talleresdeteatro.es · Gràcia, Barcelona' }, { findText: '.btn-ghost', from: 'Escribir por mail', to: 'Escriure per mail' }, { findText: '.btn-ghost', from: 'Llamar', to: 'Trucar' }, { findText: '.btn-ghost', from: 'Enviar mail', to: 'Enviar correu' }, { findText: '.overline', from: 'Dónde estamos', to: 'On som' }, ]; var PAGES = { '/': [ { sel: '.hero-mobile-badge', html: 'Estudi de teatre<br>Dir. Sebastián Mogordoy' }, { sel: '.hero-overline', html: 'Des del 2010 a Buenos Aires — Des del 2020 a Barcelona · Gràcia' }, { sel: '.hero-h1-seo', html: 'Tallers de Teatre a Barcelona' }, { sel: '.meta-line', html: 'Tallers de teatre i entrenament actoral', index: 0 }, { sel: '.meta-line', html: 'Formació per a principiants, intermedis<br>i entrenament per a actors professionals.', index: 1 }, { sel: '.meta-line', html: 'Una nova proposta de formació actoral<br>des de la improvisació dirigida.', index: 2 }, { sel: '.hero-cta-block a.btn-primary:not(.btn-wa)', html: 'Veure tallers <span class="arrow">→</span>' }, { sel: '.reviews-header-left .overline', html: 'El que diuen' }, { sel: '.reviews-h2', html: '<span class="accent-num">5</span> <span class="reviews-stars-emoji">⭐⭐⭐⭐⭐</span> <br /> Més de 100 ressenyes <br /> a Google' }, { sel: '.reviews-subtitle', html: 'Gràcies als nostres alumnes per les seves ressenyes a Google! I per la confiança, els riures, les abraçades i tot el que vivim… tant en la realitat com en la ficció.<br><br>Persones que van arribar per primera vegada al teatre i actors amb experiència comparteixen un mateix espai d\'entrenament, joc i creació. Classes de teatre a Barcelona per a tots els nivells.<br><br>Visca el teatre!' }, { sel: '.link-all', html: 'Veure totes les ressenyes <span class="arrow">→</span>' }, { findText: '.card-tag', from: 'Principiante', to: 'Principiant' }, { findText: '.card-tag', from: 'Actriz', to: 'Actriu' }, { findText: '.card-tag', from: 'Intermedio', to: 'Amb experiència' }, { sel: '.reviews-local-note', html: '<strong>Classes de teatre presencials a Gràcia, Barcelona</strong> · Principiants, Intermedis, Avançats i Cos al text' }, { sel: '.badge-txt', html: '<strong>5 / 5</strong> · Més de 100 ressenyes · Google' }, { sel: '.reviews-footer a', html: '¿Ja has entrenat amb nosaltres? Deixa la teva ressenya a Google →' }, { sel: '.levels-header .overline', html: 'Tallers de teatre a Barcelona' }, { findText: 'p', from: 'dar el salto.', to: 'donar el salt.' }, { sel: '.levels-h2', html: 'Tria el teu<br>punt d\'<br><span class="accent-word">entrada.</span>' }, { sel: '.levels-intro', html: 'Quatre recorreguts possibles per estudiar teatre a Barcelona: per als que comencen de zero, per als que volen aprofundir, per a actors que busquen un laboratori d\'entrenament i investigació, i un curs centrat en el treball amb text.' }, { sel: '.levels-announce-tag', html: 'Nous grups' }, { sel: '.levels-announce-title', html: 'Inici setembre' }, { sel: '.levels-announce-badge', html: 'Cursos de matrícula oberta. Pots començar quan vulguis.' }, { sel: '.levels-announce-cta', html: 'Apunta\'t!' }, { sel: '#principiantes .level-card-subtitle', html: 'La creació de l\'artifici. Formació.' }, { sel: '#principiantes .level-card-title', html: 'Principiants' }, { sel: '#principiantes .level-card-cta', html: 'Més info i inscripció — Principiants →' }, { sel: '#intermedios .level-card-subtitle', html: 'La inscripció del propi. Entrenament.' }, { sel: '#intermedios .level-card-title', html: 'Intermedis' }, { sel: '#intermedios .level-card-cta', html: 'Més info i inscripció — Amb experiència →' }, { sel: '#avanzados .level-card-subtitle', html: 'El ser mirat. Laboratori.' }, { sel: '#cuerpo-al-texto .level-card-subtitle', html: 'Escenes de text, Monòlegs' }, { sel: '#avanzados .level-card-title', html: 'Avançats' }, { sel: '#cuerpo-al-texto .level-card-title', html: 'Cos al text' }, { sel: '#avanzados .level-card-cta', html: 'Més info i inscripció — Avançats →' }, { sel: '#cuerpo-al-texto .level-card-cta', html: 'Més info i inscripció — Cos al text →' }, { sel: '.galeria-overline', html: 'Fotos i vídeos' }, { sel: '.cell-value', html: 'Primera setmana de classes<br>de prova sense càrrec.', index: 1 }, { sel: '#principiantes .level-card-text', html: 'Per a persones sense experiència prèvia — o amb ganes de tornar a jugar. El més important és passar-la bé, desconnectar i descobrir el plaer d\'actuar. Improvisació, cos, escolta i primeres eines actorals per entrar en la ficció sense por.' }, { sel: '#intermedios .level-card-text', html: 'Per a qui ja té experiència i vol aprofundir i entrenar actuació. Personatge, presència, desig, conflicte i poètica personal.' }, { sel: '#avanzados .level-card-text', html: 'Laboratori d\'investigació tècnica i desenvolupament de la poètica. L\'actor com a força generadora de teatralitat: un cos disposat, entrenat, vibrant. L\'actuació, per davant del relat.' }, { sel: '#cuerpo-al-texto .level-card-text', html: 'Explorarem escenes i monòlegs des del cos, l\'estat i les forces invisibles que travessen cada situació. Text, ritme, sonoritat i conflicte com a matèria viva per actuar des d\'una presència real i no des de la representació.' }, { sel: '#principiantes .level-card-schedule', html: 'Dimarts &nbsp;·&nbsp; 19 a 22h' }, { sel: '#intermedios .level-card-schedule', html: 'Dijous &nbsp;·&nbsp; 19 a 22h' }, { sel: '#avanzados .level-card-schedule', html: 'Dimecres &nbsp;·&nbsp; 19 a 22h', index: 0 }, { sel: '#cuerpo-al-texto .level-card-schedule', html: 'Dilluns &nbsp;·&nbsp; 19 a 22h', index: 0 }, { sel: '#principiantes .level-card-details summary', html: 'Llegir descripció completa <span class="dets-arrow">↓</span>' }, { sel: '#intermedios .level-card-details summary', html: 'Llegir descripció completa <span class="dets-arrow">↓</span>' }, { sel: '#avanzados .level-card-details summary', html: 'Llegir descripció completa <span class="dets-arrow">↓</span>' }, { sel: '#info-principiantes .level-info-text', html: 'Vols estudiar per primera vegada? En aquesta primera etapa els participants formaran part d\'un espai diferent als de la seva vida quotidiana, amb altres regles i altres possibilitats, juntament amb un grup de persones de diverses edats. La proposta és treballar amb cadascú, des del joc, transcendint cap al teatral. Que vulguin donar-se permís per tornar a jugar, desinhibir-se, perdre la por a l\'exposició, donant credibilitat a les situacions de ficció i descobrint la pròpia potència expressiva. Que puguin "fracturar el real" per alterar el quotidià, soltant el "jo social" i donant lloc a l\'escena de ficció, possibilitant un encontre diferent amb un mateix i amb els altres.<br><br>Un espai per als qui desitgen començar a actuar o tornar a connectar amb el joc, la imaginació i la presència. Treballarem improvisació, escolta, disponibilitat, cos, vincle i primeres eines actorals per entrar en la ficció des de l\'acció i no des de la idea. Explorarem l\'entrenament com un territori de llibertat expressiva on l\'escena apareix com a experiència viva, sensible i compartida.' }, { sel: '#info-intermedios .level-info-text', html: 'Treballarem perquè els participants dominin tècnicament la seva eina i que puguin comprendre\'s —més que com la idea d\'un personatge— com una força poètica, un cos disposat, entrenat, vibrant, que en el moment d\'actuar posa en joc tots els seus sentits i aconsegueix manejar tant la percepció multidireccional com la radiació de la pròpia energia, per mitjà de la improvisació dirigida.<br><br>S\'assimila la tècnica i s\'aferma la poètica. L\'activitat demana major compromís i comença a desplegar major complexitat i profunditat en el encontre amb l\'actuació. Entrenarem i crearem escenes per presentar a fi de cicle davant els nostres amics i familiars.<br><br>Un espai d\'aprofundiment per a actors, actrius i estudiants avançats, que ja van tenir un recorregut previ i desitgen ampliar el seu entrenament. Investigarem escena, conflicte, presència, desig, imaginari i construcció de materials actorals des d\'una recerca tècnica i poètica. El treball estarà orientat a desenvolupar una major complexitat expressiva, enfortint la relació entre cos, actuació i mirada pròpia dins de l\'escena.' }, { sel: '#info-avanzados .level-info-text', html: 'Investiguem el teatre, l\'actuació, la teatralitat i la seva poètica com a llenguatge, des de la improvisació dirigida. Comprenem l\'actuació com la principal força generadora de teatralitat. A través de l\'entrenament busquem generar eines per transcendir els límits de la representació i potenciar la poètica personal dels participants.<br><br>Treballarem perquè els participants dominin tècnicament la seva eina i puguin comprendre\'s, més que com la idea d\'un personatge, com una força poètica: un cos disposat, entrenat, vibrant. L\'actuació, per davant del relat. El relat com a excusa per afirmar el ser. El ser, mirat. El material creat es presenta en funcions reals dins del cicle La tirania del desig.' }, { sel: '#info-cuerpo-al-texto .level-info-text', html: 'El treball sobre escenes de text i monòlegs estarà centrat en comprendre que actuar un text no significa "dir bé" unes paraules, sinó descobrir quines forces el produeixen. Analitzarem les tensions que organitzen cada situació, investigant com moltes vegades la veritable lògica de l\'escena no coincideix amb la lògica racional del text escrit. L\'actuació apareix justament en aquella fricció.<br><br>Ens interessa entendre que les paraules no surten solament d\'una idea, sinó d\'un cos travessat per un estat. Un cos afectat, vibrant, desitjant, resistint, manipulant, fugint, necessitant alguna cosa de l\'altre. El text serà abordat doncs com a matèria viva: acció, impuls, respiració i comportament.<br><br>Treballarem també sobre les dimensions sonores i musicals de l\'actuació: el ritme intern de l\'escena, les velocitats, les pauses, les ruptures, la melodia de les frases, la respiració i la relació entre so i sentit.<br><br>La recerca serà que cada actor pugui construir una relació orgànica i poètica amb el text, allunyant-se de la representació il·lustrativa per trobar una actuació viva, present i travessada per veritables forces escèniques.' }, { sel: '.mirada-hero .overline', html: 'La nostra mirada' }, { sel: '.mirada-hero h2', html: 'El teatre <br /> com un <br><span style="color:var(--accent);">superjoc.</span>' }, { sel: '.mirada-hero p', html: 'Actuar és un acte conscient, tècnic, poètic, lúdic i expressiu. La nostra pedagogia no transmet continguts: t\'acompanyem en el teu procés creatiu.', index: 0 }, { sel: '.mirada-hero p', html: 'El teatre és el territori on pots ser tot allò que no ets. Un superjoc que t\'invita a descobrir una nova forma d\'habitar el món, d\'estar amb altres, d\'arriscar.', index: 1 }, { sel: '.mirada-hero p', html: 'Si busques classes de teatre a Barcelona que et permetin explorar la teva creativitat, connectar amb el teu cos i transformar el teu potencial expressiu — has arribat al lloc indicat.', index: 2 }, { sel: '.metodo-header .overline', html: 'Metodologia' }, { sel: '.metodo-header h2', html: 'Els nostres tallers de teatre a Barcelona' }, { findText: '.metodo-item-title', from: 'Sin experiencia previa', to: 'Sense experiència prèvia' }, { findText: '.metodo-item-title', from: 'El cuerpo como protagonista', to: 'El cos com a protagonista' }, { findText: '.metodo-item-title', from: 'Desarrollo integral', to: 'Desenvolupament integral' }, { findText: '.metodo-item-title', from: 'Poética personal', to: 'Poètica personal' }, { findText: '.metodo-item-title', from: 'Enfoque en el «Aquí y Ahora»', to: 'Enfocament en l\'«Aquí i Ara»' }, { findText: '.metodo-item-title', from: 'Los encuentros', to: 'Les trobades' }, { sel: '.metodo-item-text', html: 'Si mai has actuat, aquest és el teu lloc! Els nostres grups per a principiants estan dissenyats per a persones sense cap experiència, on el joc i la improvisació són el punt de partida perquè desenvolupis el teu camp imaginari.', index: 0 }, { sel: '.metodo-item-text', html: 'Inspirats en grans mestres com Raúl Serrano i Ricardo Bartís, treballem el cos no només com una eina expressiva, sinó com el territori on s\'inscriu el conflicte, un llenguatge que no necessita paraules, un lloc de contradicció i veritat.', index: 1 }, { sel: '.metodo-item-text', html: 'Fomentem la desinhibició, la confiança i la creativitat. Aquí podràs donar-te permís per tornar a jugar, equivocar-te i expandir-te, allunyant-te del «jo social» i fer un salt al camp imaginari, on tot el que t\'imaginis pot passar.', index: 2 }, { sel: '.metodo-item-text', html: 'Creiem que la teva poètica personal és el relat. No busquem actors genèrics, sinó alliberar la teva veu pròpia i singular, aquella «força expressiva» que et fa únic.', index: 3 }, { sel: '.metodo-item-text', html: 'T\'ensenyem a activar el present escènic, a vincular-te sense guió previ i a permetre que el teu cos estigui disposat a l\'error i a la troballa.', index: 4 }, { sel: '.metodo-item-text', html: 'Les trobades setmanals de 3 hores inclouen entrenament col·lectiu, improvisació d\'escenes i reflexió compartida per integrar l\'aprenentatge.<br><br>Tenim molts vestuaris, sabates, perruques, objectes, llums perquè l\'experiència sigui espectacular!', index: 5 }, { sel: '.lect-grid > div > span', html: 'Lectures' }, { sel: '.lect-grid > div > h3', html: 'Pensar<br>el teatre.' }, { sel: '.lect-grid > div > p', html: 'Articles sobre actuació, cos, imatge i procés creatiu.' }, { findText: '.lect-grid span', from: 'Técnica actoral', to: 'Tècnica actoral' }, { findText: '.lect-grid span', from: 'Filosofía', to: 'Filosofia' }, { findText: '.lect-grid span', from: 'Entrenamiento', to: 'Entrenament' }, { findText: '.lect-grid span', from: 'Por qué actuar no es representar', to: 'Per què actuar no és representar' }, { findText: '.lect-grid span', from: 'El juego como origen', to: 'El joc com a origen' }, { sel: '.lect-grid > div > a[href="/blog/"]', html: 'Veure tots els articles →' }, { sel: '.lect-grid > a > span:first-child', html: 'Qüestionaris' }, { sel: '.lect-grid > a > h3', html: 'Posa\'l<br>a prova.' }, { sel: '.lect-grid > a > p', html: 'Preguntes sobre els conceptes de l\'entrenament: presència, imatge, cos, improvisació. Per saber el que saps, i el que encara no.' }, { sel: '.lect-grid > a > span:last-child', html: 'Anar als qüestionaris →' }, { sel: '.nosotros-header .overline', html: 'Qui som' }, { sel: '.nosotros-card-role', html: 'Director · Professor', index: 0 }, { sel: '.nosotros-card-role', html: 'Professora', index: 1 }, { sel: '.prof-role', html: 'Coord. General · Professor', index: 0 }, { sel: '.prof-role', html: 'Professora', index: 1 }, { sel: '.nosotros-15anos-titulo', html: '15 anys <br><span class="nosotros-juntos">junts.</span>' }, { sel: '.nosotros-card-text', html: 'Vam começar l\'any 2010 amb 8 inoblidables alumnes al Camarín de las Musas. Avui continuem fent i pensant el teatre que ens agrada.', index: 2 }, { sel: '.nosotros-card-text', html: 'Actualment forma part de l\'elenc protagonista de <em>El Fill</em>, de Jon Fosse, dirigida per Ferran Utzet, estrenada al Teatre Lliure. L\'obra va participar al Festival Internacional de Buenos Aires i es va estrenar a la Sala Beckett. Recentment va formar part de l\'elenc de la pel·lícula <em>El professor</em>, produïda per Netflix.', index: 0 }, { sel: '.nosotros-card-text', html: 'Actriu, gestora cultural i docent de teatre. Va coordinar les activitats del teatre Silencio de Negras i va crear juntament amb diversos grups diferents cicles: Enredadera a la llibreria La Libre, Derrapé a Sala de Màquines, Circuito Lumínico i Lo que dura una canción. Docent a Buenos Aires i Barcelona.', index: 1 }, { sel: '#nosotros .container > div:last-child h2', html: 'Tenim <br><span style="color:var(--accent);">el teatre.</span>' }, { sel: '.nosotros-card-text', html: 'En un món on la realitat ens empeny a sobreviure enmig de diferents guerres, el teatre continua sent la nostra trinxera, el nostre refugi, lloc d\'expressió, experimentació i investigació, de l\'humà i del procés creatiu.', index: 3 }, { sel: '.nosotros-card-text', html: 'Quan la vida es posa una mica avorrida o massa agressiva, el teatre ens proposa intensitats poètiques i expressives que ens fan soltar la representació "del personatge que som a la vida" per llençar-nos en un no saber que ens obre a altres possibilitats d\'existència, expandint la nostra experiència, habitant forces i situacions que no ens són pròpies. Ens convida a ser tot allò que no som.', index: 4 }, { sel: '.prof-bio', html: 'Actualment forma part de l\'elenc protagonista de <em>El Fill</em>, de Jon Fosse, dirigida per Ferran Utzet, estrenada al Teatre Lliure. L\'obra va participar al Festival Internacional de Buenos Aires i es va estrenar a la Sala Beckett. Recentment va formar part de l\'elenc de la pel·lícula <em>El professor</em>, produïda per Netflix.', index: 0 }, { sel: '.prof-bio', html: 'Actriu, gestora cultural i docent de teatre. Va coordinar les activitats del teatre Silencio de Negras i va crear juntament amb diversos grups diferents cicles: Enredadera a la llibreria La Libre, Derrapé a Sala de Màquines, Circuito Lumínico i Lo que dura una canción. Docent a Buenos Aires i Barcelona.', index: 1 }, { sel: '.comunidad-section .overline', html: 'Uneix-te' }, { sel: '.comunidad-h2', html: 'Més enllà <br /> de la ficció.' }, { sel: '.comunidad-text', html: 'Barcelona és una ciutat vibrant, plena de persones de diverses edats, costums i nacionalitats. Cultivem un espai de creació, trobada real, expressió i construcció social. A més de desenvolupar el teu treball actoral, coneixes gent, compartiu i creeu amb els vostres companys. Les classes es transformen en una experiència acumulativa de rialles, assoliments i amistats.' }, { sel: '.comunidad-cta-block .btn-wa', html: 'Reservar classe de prova <span class="arrow">→</span>' }, { sel: '.noticias-section .overline', html: 'En cartellera' }, { sel: '#noticias h2', html: 'Sebastián Mogordoy <br /> en escena.' }, { sel: '.noticia-tag', html: 'Estrena 2026 · Teatre Lliure', index: 0 }, { sel: '.noticia-text', html: 'Sebastián Mogordoy forma part de l\'elenc protagonista de <em>El Fill</em>, de Jon Fosse, dirigida per Ferran Utzet. Estrenada al Teatre Lliure de Barcelona.', index: 0 }, { sel: '.noticia-title', html: 'Eufòria i <br /> Desassossec', index: 1 }, { sel: '.noticia-text', html: 'Sebastián Mogordoy forma part de l\'elenc protagonista. Dirigida per Sergio Boris. Estrenada al Festival Temporada Alta 2024. Temporada a la Sala Beckett, Obrador Internacional de Dramatúrgia. Teatros del Canal, Madrid, 2025/26.', index: 1 }, { findText: '.noticia-link', from: 'Ver espectáculo →', to: 'Veure l\'espectacle →' }, { sel: '.faq-section .overline', html: 'Preguntes freqüents' }, { sel: '.faq-h2', html: 'Tot el que <br /> necessites saber.' }, { findText: '.faq-question', from: '¿Necesito experiencia previa para apuntarme?', to: 'Necessito experiència prèvia per apuntar-me?' }, { findText: '.faq-question', from: '¿Puedo apuntarme si soy actor o actriz con formación previa?', to: 'Puc apuntar-me si sóc actor o actriu amb formació prèvia?' }, { findText: '.faq-question', from: '¿Cómo es una clase? ¿Qué pasa en cada encuentro?', to: 'Com és una classe? Què passa en cada trobada?' }, { findText: '.faq-question', from: '¿Hay una clase de prueba gratuita?', to: 'Hi ha una classe de prova gratuïta?' }, { findText: '.faq-question', from: '¿Cuándo empieza el próximo grupo? ¿Se puede unir a uno en cualquier momento?', to: 'Quan comença el pròxim grup? Es pot incorporar algú en qualsevol moment?' }, { findText: '.faq-question', from: '¿Dónde se realizan las clases?', to: 'On es realitzen les classes?' }, { findText: '.faq-question', from: '¿Qué edades participan en los talleres?', to: 'Quines edats participen als tallers?' }, { findText: '.faq-question', from: '¿Cuánto cuesta el taller?', to: 'Quant costa el taller?' }, { findText: '.faq-question', from: '¿Se trabaja improvisación, texto o las dos cosas?', to: 'Es treballa improvisació, text o les dues coses?' }, { sel: '.faq-answer p', html: 'No. El taller de principiants està dissenyat per a persones que s\'acosten al teatre per primera vegada, o que volen tornar a connectar amb el joc i l\'escena després d\'anys. El punt de partida és la curiositat i les ganes d\'explorar. No cal saber res de bestreta.', index: 0 }, { sel: '.faq-answer p', html: 'Sí. El curs d\'Intermedis (Inscriure el propi) està pensat per a qui ja té un recorregut i vol aprofundir en tècnica, presència, conflicte i construcció d\'una poètica pròpia. El curs d\'Avançats (El ser mirat) és un laboratori d\'entrenament i investigació. I oferim també <em>Cos al text</em>, centrat en escenes i monòlegs, per a actors amb formació sòlida.', index: 1 }, { sel: '.faq-answer p', html: 'Cada trobada dura 3 hores. Combinem entrenament físic i vocal, improvisació d\'escenes i reflexió compartida sobre el treball. La metodologia part del cos, el present escènic i el vincle entre els participants. No treballem des de fórmules, sinó des de l\'aquí i ara de l\'escena.', index: 2 }, { sel: '.faq-answer p', html: 'Sí. Oferim una primera classe de prova sense cost perquè puguis viure l\'experiència abans de comprometre\'t. Només escriu-nos per WhatsApp o correu i t\'afegim a la pròxima sessió disponible.', index: 3 }, { sel: '.faq-answer p', html: 'Els grups de principiants obren al setembre, al gener i al juny segons la demanda. El pròxim grup arrencarà el juny de 2026. Els nivells intermedis i avançats tenen incorporació contínua quan hi ha places disponibles. Consulta\'ns per WhatsApp per saber l\'estat actual de cada grup.', index: 4 }, { sel: '.faq-answer p', html: 'Les classes es realitzen a l\'<strong>Espai La Mansió</strong>, al Carrer de Roger de Flor, 253, Local 2 i 3, barri de Gràcia, Barcelona (08025). És un espai ampli amb escenari, vestuari, llums i tots els recursos necessaris per a l\'entrenament actoral.', index: 5 }, { sel: '.faq-answer p', html: 'Els tallers estan oberts a adults de totes les edats. Conviuen persones de perfils molt diversos: estudiants, professionals, jubilats, actors en actiu i persones que mai han trepitjat un escenari. La diversitat d\'edats i experiències enriqueix el treball de grup.', index: 6 }, { sel: '.faq-answer p', html: 'La quota és de 100 € al mes i inclou totes les trobades del mes. No es cobra matrícula i la primera classe és sempre gratuïta. Si no arribes a pagar el total, escriu-nos i t\'expliquem les opcions de beques i mitges beques.', index: 7 }, { sel: '.faq-answer p', html: 'La improvisació dirigida és l\'eix central de tots els tallers. Al nivell avançat <em>Cos al text</em> treballem específicament sobre escenes i monòlegs, abordant el text com a matèria viva: acció, impuls, respiració i comportament, no com a recitació de paraules. A tots els nivells el cos i el present escènic són el punt de partida.', index: 8 }, { sel: '.ubicacion-section .overline', html: 'On som' }, { sel: '.ubicacion-espacio', html: 'Espai <br /> La Mansió<span>.</span>' }, { sel: '.ubicacion-dato-text', html: '<strong>Roger de Flor, 253 · Gràcia, Barcelona</strong> Local 2 i 3 · 08025 — Barcelona, Espanya', index: 0 }, { findText: '.ubicacion-dato-icon', from: 'Clases', to: 'Classes' }, { sel: '.ubicacion-dato-text', html: 'Dilluns · Dimarts · Dimecres · Dijous<br>19:00 — 22:00 h', index: 4 }, { sel: '.ubicacion-cta', html: 'Com arribar-hi →' }, { sel: '.ubicacion-mapa-label', html: 'Gràcia · Barcelona · Clica per carregar el mapa' }, { sel: '.galeria-titulo', html: 'Som imatges <br><span class="acc">que expliquem històries.</span>' }, ], '/principiantes/': [ { sel: '.hero-tag', html: 'Taller 01 · Sense experiència prèvia' }, { sel: '.hero-title', html: 'Iniciació.', index: 0 }, { sel: '.hero-title', html: 'Principiants', index: 1 }, { sel: '.hero-tagline', html: 'Per a persones amb ganes d\'expressar-se, aprendre i divertir-se, fent teatre.' }, { sel: '.hero-dir-label', html: 'Estudi de teatre' }, { sel: '.hero-meta-item', html: '<strong>Barcelona · Gràcia</strong>', index: 0 }, { sel: '.hero-meta-item', html: 'Espai La Mansió', index: 1 }, { sel: '.hero-meta-item', html: 'Places obertes', index: 2 }, { sel: '.intro-section .overline', html: 'Per a qui' }, { sel: '.intro-statement', html: 'No cal<br>haver actuat<br><span class="acc">mai.</span>' }, { sel: '.intro-pullquote p', html: 'Aquest és un lloc per no saber,<br>per equivocar-se<br>i expandir-se.' }, { sel: '.intro-cta-line span', html: 'No t\'ho pensis més i vine a provar!' }, { sel: '.intro-p', html: 'Aquest taller de teatre per a principiants està pensat per a persones que s\'acosten a l\'actuació <strong>per primera vegada</strong>, o per a qui vol tornar a connectar amb el joc, el cos i la imaginació després d\'anys sense fer-ho.', index: 0 }, { sel: '.intro-p', html: 'No s\'actua bé ni malament. S\'actua des d\'on cadascú és i comprèn què és actuar, no cal que sàpiguen fer-ho. Als entrenaments s\'entra en un territori diferent al quotidià, amb altres regles, altres possibilitats, un altre ús del temps, del cos i del camp imaginari. El punt de partida és la curiositat. L\'únic necessari són les ganes d\'animar-se.', index: 1 }, { sel: '.intro-p', html: 'Entrenarement amb cada persona, <strong>des del joc corporal</strong>, transcendint cap al teatral, per acompanyar-te en un procés acumulatiu i descobrir les teves possibilitats expressives i la teva poètica personal, per mitjà de la improvisació dirigida.', index: 2 }, { sel: '.intro-p', html: 'Els grups estan conformats per <strong>adults de tots dos sexes, de diferents edats, de diferents costums i nacionalitats</strong>. T\'esperem! És moment d\'actuar.', index: 3 }, { findText: '.intro-kw-tag', from: 'Improvisación teatral', to: 'Improvisació teatral' }, { findText: '.intro-kw-tag', from: 'Formación actoral', to: 'Formació actoral' }, { findText: '.intro-kw-tag', from: 'Gràcia, Barcelona', to: 'Gràcia, Barcelona' }, { findText: '.intro-kw-tag', from: 'Adultos', to: 'Adults' }, { findText: '.intro-kw-tag', from: 'Desde cero', to: 'Des de zero' }, { sel: '.porque-section .overline', html: 'El perquè' }, { sel: '.porque-headline', html: 'Actuar<br>és una altra<br><span>forma</span><br>d\'estar.' }, { sel: '.porque-intro', html: 'No per convertir-se en una altra persona. Sinó per descobrir altres possibilitats de la pròpia. El teatre no t\'ensenya a fingir, t\'ensenya a estar present.' }, { sel: '.porque-concept', html: 'Joc adult', index: 0 }, { sel: '.porque-concept', html: 'Presència real', index: 1 }, { sel: '.porque-concept', html: 'Vincle genuí', index: 2 }, { sel: '.porque-concept', html: 'Llibertat expressiva', index: 3 }, { sel: '.porque-desc', html: 'Hi ha coses que només ocorren quan deixem de controlar-ho tot. El teatre activa aquesta part, la que sap jugar, inventar, creure en l\'impossible.', index: 0 }, { sel: '.porque-desc', html: 'A escena no es pot estar en un altre lloc. Aquella concentració en el present, en el cos, en l\'altre, en el que passa, és alguna cosa que s\'entrena i que canvia com et relaciones amb el món.', index: 1 }, { sel: '.porque-desc', html: 'El grup que es forma en un taller de teatre és diferent al de qualsevol altre context. Hi ha alguna cosa en l\'exposició compartida que genera llaços reals.', index: 2 }, { sel: '.porque-desc', html: 'Sortir dels hàbits expressius propis. Habitar altres estats, altres ritmes, altres lògiques. Això amplia alguna cosa, no sols a l\'escenari.', index: 3 }, { sel: '.editorial-strip-caption p', html: 'Creure és crear.<br>Fes el primer pas i la resta et sorprendrà.' }, { sel: '.manifesto-line', html: 'Tornar a jugar, creure, obrir-te sense jutjar-te', index: 0 }, { sel: '.manifesto-line', html: 'Fracturar allò real, alterant el quotidià', index: 1 }, { sel: '.manifesto-line', html: 'Obrir-te a un univers amb altres regles i altres possibilitats', index: 2 }, { sel: '.manifesto-line', html: 'Reconèixer el teu cos com una eina d\'expressió', index: 3 }, { sel: '.manifesto-line', html: 'Investigar en el teu propi univers associatiu', index: 4 }, { sel: '.manifesto-line', html: 'Usar el teu cos «poèticament» des del primer dia', index: 5 }, { sel: '.hacer-lead', html: 'A la nostra escola de teatre trobaràs un espai de <strong>trobada, expressió, diversió, treball físic, desenvolupament del camp imaginari, formació actoral i construcció social</strong>, on comenzaràs des de zero.', index: 0 }, { sel: '.hacer-lead', html: 'Esperem que aquestes trobades et permetin <strong>posar el cos i el desig en acció</strong>, i a més de passar-ho bé i conèixer gent.', index: 1 }, { sel: '.proceso-section .overline', html: 'L\'entrenament actoral' }, { sel: '.proceso-h2', html: 'Cada classe,<br><span class="acc">una aventura.</span>' }, { sel: '.proceso-nota', html: 'Comptem amb una àmplia selecció de <strong>vestuari, objectes i llums</strong> perquè l\'experiència escènica sigui completa <strong>des del primer dia</strong>.', index: 0 }, { sel: '.proceso-nota', html: 'La metodologia del taller es construeix sobre tres eixos: <strong>l\'entrenament col·lectiu, la improvisació d\'escenes i la reflexió compartida</strong>. A partir dels potencials individuals i grupals, treballem possibilitant una qualitat de trobada diferent amb un mateix i amb els altres. Aquí começaràs a incorporar les eines necessàries per abordar aquest joc adult que proposa el teatre.', index: 1 }, { sel: '.proceso-nota', html: 'L\'objectiu és <strong>fracturar allò real</strong>, alterar el quotidià, i donar el salt cap a aquell altre costat on tot pot passar: el camp imaginari. Un espai on el cos, la veu i la presència es converteixen en instruments d\'expressió i des de la primera sessió comences a incorporar les eines que proposa el quefer teatral en un treball acumulatiu i molt intens d\'observació i presa de consciència de la pròpia expressivitat, sempre en contacte <strong>AMB L\'ALTRE</strong>.', index: 2 }, { sel: '.proceso-title', html: 'Cos <br><span class="acc">i presència</span>', index: 0 }, { sel: '.proceso-text', html: 'Cada classe comença amb el cos. Exercicis de disponibilitat, escolta i activació del present escènic. No ioga, no relaxació, entrenament actoral des del primer encontre.', index: 0 }, { sel: '.proceso-title', html: 'Improvisació <br><span class="acc">dirigida</span>', index: 1 }, { sel: '.proceso-text', html: 'L\'eix central del treball. Tots a l\'espai actuant alhora, conduïts pel coordinador. S\'aprèn a escoltar, reaccionar i sostenir la ficció des de l\'acció, no des de la idea.', index: 1 }, { sel: '.proceso-title', html: 'Joc <br><span class="acc">i ficció</span>', index: 2 }, { sel: '.proceso-text', html: 'S\'activa el camp imaginari, aquell territori on tot allò que t\'imagines pot passar. Situacions impossibles, personatges inesperats, altres mons. Sense vergonya, sense judici.', index: 2 }, { sel: '.proceso-title', html: 'Improvisació <br><span class="acc">d\'escenes</span>', index: 3 }, { sel: '.proceso-text', html: 'Improvisem escenes breus des de diferents estímuls. S\'inaugura l\'escolta real, el contacte, l\'afectació mútua. No s\'actua sol: s\'actua amb l\'altre. Això ho canvia tot.', index: 3 }, { sel: '.proceso-title', html: 'Grup <br><span class="acc">i confiança</span>', index: 4 }, { sel: '.proceso-text', html: 'El grup és la condició del treball. Es construeix un espai on equivocar-se és benvingut, on l\'error no paralitza sinó que obre possibilitats. Això és el que fa diferent aquest teatre.', index: 4 }, { sel: '.proceso-title', html: 'Mostra <br><span class="acc">de fi de cicle</span>', index: 5 }, { sel: '.proceso-text', html: 'Al tancament de l\'any, el grup crea i presenta una mostra per a amics i familiars. No és una obra formal, és una trobada on obrim el procés. El primer de molts que aniran creant junts.', index: 5 }, { sel: '.video-section .overline', html: 'El taller en vídeo' }, { sel: '.video-h2', html: 'Fer el<br>salt.' }, { sel: '.test-overline', html: 'Testimonis' }, { sel: '.test-h2', html: 'El que diuen els que ja <span class="acc">hi eren.</span>' }, { sel: '.test-card-label', html: 'Testimoni' }, { sel: '.reels-section .overline', html: 'Benvinguts' }, { sel: '.info-section .overline', html: 'Informació pràctica' }, { sel: '.info-col-title', html: 'El taller', index: 0 }, { sel: '.info-col-title', html: 'La inscripció', index: 1 }, { findText: '.info-label', from: 'Nivel', to: 'Nivell' }, { findText: '.info-label', from: 'Frecuencia', to: 'Freqüència' }, { findText: '.info-label', from: 'Días y grupos', to: 'Dies i grups' }, { findText: '.info-label', from: 'Lugar', to: 'Lloc' }, { findText: '.info-label', from: 'Incorporación', to: 'Incorporació' }, { findText: '.info-label', from: 'Coordinan', to: 'Coordinen' }, { findText: '.info-label', from: 'Clase de prueba', to: 'Classe de prova' }, { findText: '.info-label', from: 'Grupo', to: 'Grup' }, { sel: '.info-value', html: 'Principiants, sense experiència prèvia', index: 0 }, { sel: '.info-value', html: '1 trobada setmanal · <strong>3 hores per classe</strong>', index: 1 }, { sel: '.info-value', html: 'Espai La Mansió<br>Roger de Flor 253 · Gràcia, Barcelona', index: 3 }, { sel: '.info-value', html: 'Pots incorporar-te en qualsevol moment de l\'any', index: 4 }, { sel: '.info-value', html: '<strong>Sense cost</strong> per a grups ja iniciats.', index: 6 }, { sel: '.info-value', html: '100 €/mes · Sense matrícula. <strong>Primera classe gratuïta.</strong>', index: 7 }, { sel: '.info-value', html: 'Reduït · màxim 12 persones', index: 8 }, { sel: '.ubicacion-section .overline', html: 'On som' }, { sel: '.faq-section .overline', html: 'Preguntes freqüents' }, { sel: '.faq-h2', html: 'Tot el que<br>et preguntes.' }, { findText: '.faq-q', from: '¿Necesito experiencia previa para el taller de principiantes?', to: 'Necessito experiència prèvia per al taller de principiants?' }, { findText: '.faq-q', from: '¿Qué pasa si soy tímido?', to: 'Què passa si sóc tímid?' }, { findText: '.faq-q', from: '¿Qué edades tienen los participantes?', to: 'Quines edats tenen els participants?' }, { findText: '.faq-q', from: '¿Se trabaja con textos y obras?', to: 'Es treballa amb textos i obres?' }, { findText: '.faq-q', from: '¿Hay muestra o función al final del año?', to: 'Hi ha mostra o funció al final de l\'any?' }, { findText: '.faq-q', from: '¿Puedo incorporarme en cualquier momento del año?', to: 'Puc incorporar-me en qualsevol moment de l\'any?' }, { findText: '.faq-q', from: '¿Cuánto duran las clases y con qué frecuencia?', to: 'Quant duren les classes i amb quina freqüència?' }, { findText: '.faq-q', from: '¿Dónde se hacen las clases de teatro?', to: 'On es fan les classes de teatre?' }, { sel: '.faq-a', html: 'No. Aquest taller està dissenyat específicament per a persones que mai han fet teatre. No cal cap experiència prèvia. El punt de partida és la curiositat i les ganes de provar, res més.', index: 0 }, { sel: '.faq-a', html: 'La timidesa és benvinguda. No es tracta de ser extravertit ni d\'actuar bé. El treball es fa des del cos i el joc, en un grup on equivocar-se forma part del procés. Molts alumnes arriben amb por, i descobreixen que això canvia bastant de pressa.', index: 1 }, { sel: '.faq-a', html: 'Joves i adults de diferents edats, professions i orígens. Aquesta barreja és part del que fa el grup tan interessant i el treball tan viu.', index: 2 }, { sel: '.faq-a', html: 'L\'eix del treball és la improvisació dirigida, no el text memoritzat. En el nivell de principiants es treballa principalment des del cos, l\'acció i la ficció improvisada. El text entra més endavant, com una eina més dins del treball actoral.', index: 3 }, { sel: '.faq-a', html: 'Sí. Al tancament de cada cicle el grup crea i presenta una mostra per a amics i familiars. No és una obra formal, és una trobada on es comparteix el procés de l\'any. Una experiència diferent per a tots els que hi participen.', index: 4 }, { sel: '.faq-a', html: 'Sí. L\'estructura del taller permet incorporar-se en qualsevol moment. Si hi ha un grup nou formant-se, et recomanem reservar plaça directament, les vacants són limitades i els grups s\'omplen de pressa.', index: 5 }, { sel: '.faq-a', html: 'Cada trobada dura 3 hores, una vegada per setmana. Aquesta freqüència permet que el treball s\'acumuli i s\'aprofundeixi, sense ser una càrrega al calendari setmanal.', index: 6 }, { sel: '.faq-a', html: 'A l\'Espai La Mansió, Carrer de Roger de Flor 253, Local 2 i 3, al barri de Gràcia, Barcelona. Molt ben comunicat en metro: estacions Verdaguer i Sagrada Família (L2/L5).', index: 7 }, { sel: '.cta-eyebrow', html: 'Taller de teatre per a principiants · Barcelona · Gràcia' }, { sel: '.cta-line1', html: 'Potser hi ha alguna cosa en tu' }, { sel: '.cta-title', html: 'que vol<br>entrar en<br><span class="acc">escena.</span>' }, { sel: '.cta-sub', html: 'La primera classe és sense cost. Vine a conèixer l\'espai, el grup i la forma de treballar. Sense compromís, només per veure com se sent.' }, { sel: '.cta-nota', html: 'Places limitades · Espai La Mansió · Roger de Flor 253 · Gràcia, Barcelona' }, { sel: '.galeria-universo .overline', html: 'El taller en imatges' }, { sel: '.galeria-titulo', html: 'Som imatges<br><span class="acc">que expliquem històries.</span>' }, { sel: '.gallery .overline', html: 'Galeria' }, { sel: '.hacer-headline', html: '<span class="hacer-verb">Fem</span><br>teatre.' }, { sel: '.hacer-headline', attr: 'aria-label', val: 'Fem teatre' }, { sel: '.video-p', html: 'Tres hores per setmana. Un espai pensat perquè alguna cosa real passi.', index: 0 }, { sel: '.video-p', html: 'Coord. <strong>Sebastián Mogordoy</strong><br>Espai La Mansió · Gràcia, Barcelona', index: 1 }, { findText: '.test-card-label', from: 'Testimonio', to: 'Testimoni' }, { findText: '.info-label', from: 'Precio', to: 'Preu' }, { sel: '.info-value', html: '<strong>Principiants · Dimarts · 19 a 22 h</strong><br><strong>Principiants+ · Dijous · 19 a 22 h</strong><br><span class="info-note">Temporada 2026/27 · Inscripció oberta.</span>', index: 2 }, { findText: '.info-note', from: 'Si no llegas a pagar el total, escríbenos y te contamos las opciones de becas y medias becas.', to: 'Si no arribes a pagar el total, escriu-nos i t\'expliquem les opcions de beques i mitges beques.' }, { sel: 'a.btn-primary[href*="principiantes."]', html: 'Consultar per WhatsApp <span class="arrow">→</span>' }, { sel: 'a[href*="taller-bienvenida"] span:first-of-type', html: 'Carta de benvinguda al taller' }, { sel: 'a[href*="taller-bienvenida"] span:last-of-type', html: 'PDF · Descarregar' }, ], '/intermedios/': [ { sel: '.hero-tag', html: 'Taller 02 · Intermedis' }, { sel: '.hero-title', html: 'Intermedis.' }, { sel: '.hero-tagline', html: 'Per a actors professionals i estudiants avançats que volen aprofundir, crear escenes i trobar la seva poètica.' }, { sel: '.hero-dir-label', html: 'Estudi de teatre' }, { sel: '.intro-section .overline', html: 'Per a qui' }, { sel: '.intro-statement', html: 'La ficció<br>surt de<br><span class="acc">tu.</span>' }, { sel: '.intro-pullquote p', html: 'El material és el teu. El treball és trobar com posar-lo a escena.' }, { sel: '.intro-cta-line span', html: 'Incorporació per entrevista' }, { sel: '.intro-p', html: 'Si ja has fet teatre i vols continuar entrenant sense tornar a començar, en aquesta <strong>escola de teatre</strong> s\'aprofundeix en situacions de major complexitat tècnica i poètica: vincles més densos, materials més personals, improvisacions on l\'error no paralitza, sinó que obre.', index: 0 }, { sel: '.intro-p', html: 'El treball es focalitza en una recerca de llenguatge propi: entrenant mitjançant la improvisació dirigida, aprofundint l\'opinió personal i el llenguatge teatral. No es tracta de tècnica com a fi, sinó com a camí cap a la poètica.', index: 1 }, { sel: '.intro-p', html: 'Els participants comencen a fer-se càrrec de la seva poètica personal i de les seves decisions d\'actuació. A reconèixer la seva imatge, la seva potència particular, i a portar la seva capacitat expressiva al màxim.', index: 2 }, { sel: '.intro-p', html: 'Els grups barrejen trajectòries: actors de formació acadèmica, persones que porten anys en tallers, gent del teatre independent. <strong>Aquesta diversitat és part constitutiva del treball col·lectiu.</strong> Si estàs donant els teus primers passos a escena, pots veure el <a href="/principiantes/" style="color:var(--accent); text-decoration:underline; text-underline-offset:3px;">taller de principiants</a>.', index: 3 }, { sel: '.intro-break-text', html: 'És el moment en el qual<br>es comença a comprendre<br>i dominar les pròpies forces.' }, { findText: '.intro-kw-tag', from: 'Improvisación avanzada', to: 'Improvisació avançada' }, { findText: '.intro-kw-tag', from: 'Creación de escenas', to: 'Creació d\'escenes' }, { findText: '.intro-kw-tag', from: 'Poética personal', to: 'Poètica personal' }, { findText: '.intro-kw-tag', from: 'Adultos con experiencia', to: 'Adults amb experiència' }, { sel: '.escena-section .overline', html: 'L\'entrenament' }, { sel: '.escena-h2', html: 'El treball<br>sobre l\'<span>escena.</span>' }, { sel: '.escena-intro', html: 'Una trobada setmanal de tres hores. L\'eix no és la tècnica com a fi sinó com a camí: el cos disponible, l\'escolta activa, la ficció sostinguda. Es treballa sempre des de l\'acció, mai des de la idea prèvia.' }, { sel: '.escena-concept', html: 'Improvisació <br><span class="acc">dirigida</span>', index: 0 }, { sel: '.escena-text', html: 'El treball no és lliure: té estructura, direcció i rigor. La improvisació és el territori on l\'actor entra en contacte real amb el que succeeix, sense xarxa, sense guió previ. El que ocorre a escena és el que importa.', index: 0 }, { sel: '.escena-concept', html: 'Forces <br><span class="acc">en joc</span>', index: 1 }, { sel: '.escena-text', html: 'Què mou un actor. Què el deté. Què el transforma. El treball sobre les forces a escena (el desig, l\'obstacle, el conflicte, el vincle) és el que dóna espessor a una escena i la distingeix de l\'exercici.', index: 1 }, { sel: '.escena-concept', html: 'Poètica <br><span class="acc">personal</span>', index: 2 }, { sel: '.escena-text', html: 'Cada actor té un univers propi: imatges, obsessions, ritmes, territoris que li pertanyen. El treball és descobrir-los, nomenar-los i començar a habitar-los des de l\'escena. Això és el que fa que un actor sigui inconfusible.', index: 2 }, { sel: '.escena-concept', html: 'Creació <br><span class="acc">d\'escenes</span>', index: 3 }, { sel: '.escena-text', html: 'De la improvisació al material propi. El grup treballa sobre escenes que es van construint, revisant i aprofundint al llarg de l\'any. Al tancament del cicle, aquell material es presenta en una mostra oberta i el cicle <em>La tirania del desig</em>.', index: 3 }, { sel: '.metodo-section .overline', html: 'La metodologia' }, { sel: '.metodo-headline', html: 'Tres eixos. <br><span class="acc">Un entrenament.</span>' }, { sel: '.metodo-lead', html: 'Cada classe es construeix sobre tres pilars que es retroalimenten. No són fases separades: se superposen, es tensionen, s\'aprofundeixen junts. La improvisació mai és descans. L\'entrenament mai és rutina.' }, { sel: '.metodo-concept', html: 'Entrenament col·lectiu', index: 0 }, { sel: '.metodo-desc', html: 'Cada classe comença amb el cos: escalfament actoral, disponibilitat, presència, escolta de l\'espai i del grup. No és escalfament: és l\'inici real del treball. El cos és el primer instrument. A aquest nivell, es tracta d\'afinar-lo cada vegada més.', index: 0 }, { sel: '.metodo-concept', html: 'Creació d\'escenes', index: 1 }, { sel: '.metodo-desc', html: 'L\'eix central del treball. S\'improvisen escenes amb diferents estímuls i amb major complexitat que en el nivell inicial: vincles més densos, situacions més exigents, materials més personals. L\'error no paralitza: obre. Aquí l\'exigència és major perquè la disponibilitat també ho és.', index: 1 }, { sel: '.metodo-concept', html: 'Poètica individual', index: 2 }, { sel: '.metodo-desc', html: 'Al llarg del cicle es treballa sobre el material propi de cada actor: les seves imatges, les seves obsessions, el seu món. La reflexió compartida sobre el que sorgeix a escena permet que cada persona comenci a reconèixer i aprofundir en la seva pròpia poètica. Aquest és el treball més lent i més valuós.', index: 2 }, { sel: '.video-section .overline', html: 'Cicle de teatre' }, { sel: '.testimonios-section .overline', html: 'El que diuen' }, { sel: '.testimonios-h2', html: 'El que diuen<br>els que ja<br><span class="acc">hi eren.</span>' }, { sel: '.carousel-h2', html: 'Estem<br>en <span>moviment.</span>' }, { sel: '.info-section .overline', html: 'Informació pràctica' }, { findText: '.info-label', from: 'Nivel', to: 'Nivell' }, { findText: '.info-label', from: 'Formato', to: 'Format' }, { findText: '.info-label', from: 'Horarios', to: 'Horaris' }, { findText: '.info-label', from: 'Lugar', to: 'Lloc' }, { findText: '.info-label', from: 'Precio', to: 'Preu' }, { findText: '.info-label', from: 'Coordinación', to: 'Coordinació' }, { sel: '.info-value', html: 'Taller de teatre amb experiència prèvia: actors professionals, estudiants avançats, persones que reprenen la formació actoral.', index: 0 }, { sel: '.info-value', html: '<strong>Una vegada per setmana · 3 hores per trobada.</strong> Ritme anual amb mostra de fi de cicle.', index: 1 }, { sel: '.info-value', html: '<strong>Dijous · 19 a 22 h.</strong><br><span class="info-note">Temporada 2026/27 · Inscripció oberta.</span>', index: 2 }, { sel: '.info-value', html: '<strong>Espai La Mansió</strong> · Carrer de Roger de Flor, 253, Local 2 i 3 · Gràcia, Barcelona.<br>Metro: Verdaguer o Sagrada Família.', index: 3 }, { sel: '.info-value', html: '100 €/mes · Sense matrícula. Primera classe <strong>gratuïta.</strong><br><span class="info-note">Si no arribes a pagar el total, escriu-nos i t\'expliquem les opcions de beques i mitges beques.</span>', index: 4 }, { sel: '.info-value', html: 'Sebastián Mogordoy', index: 5 }, { sel: '.ubicacion-section .overline', html: 'On trobar-nos' }, { sel: '.ubicacion-h2', html: 'Gràcia,<br>Barcelona.' }, { sel: '.faq-section .overline', html: 'Preguntes freqüents' }, { sel: '.faq-h2', html: 'El que<br>solen preguntar.' }, { sel: '.faq-list .faq-item:nth-child(1) summary', html: 'Necessito experiència prèvia per entrar a Amb experiència? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(1) .faq-body', html: 'Sí. Aquest taller està pensat per a persones que ja han tingut contacte amb el teatre: un taller anterior, formació acadèmica, treball amb grups amateurs o professional. No cal un recorregut llarg, però sí haver trepitjat una escena i entendre de què va el treball actoral.' }, { sel: '.faq-list .faq-item:nth-child(2) summary', html: 'Quina diferència hi ha entre Principiants i Amb experiència? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(2) .faq-body', html: 'A Principiants es construeixen les bases: el cos, el joc, la ficció des de zero. A Amb experiència el punt de partida és un altre. No s\'explica què és el teatre: es treballa dins d\'ell amb major exigència, densitat i complexitat. El nivell de disponibilitat requerit és major i el treball va cap a la poètica personal de cada actor.' }, { sel: '.faq-list .faq-item:nth-child(3) summary', html: 'Quin tipus d\'escenes es treballen? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(3) .faq-body', html: 'Escenes improvisades a partir de diferents estímuls: situacions, vincles, imatges, estats. Al llarg de l\'any aquelles improvisacions es van convertint en material propi de cada actor. No es munten obres d\'autor: es construeix material des del treball a sala.' }, { sel: '.faq-list .faq-item:nth-child(4) summary', html: 'Es treballa amb text i monòlegs? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(4) .faq-body', html: 'L\'eix és la improvisació dirigida, no el text memoritzat. El text pot aparèixer com estímul o territori de treball, però no s\'assagen parlaments ni es munten escenes d\'obres. Si t\'interessa el treball específic amb text dramàtic, això pertany al taller Cos al Text.' }, { sel: '.faq-list .faq-item:nth-child(5) summary', html: 'Hi ha mostra o presentació al final de l\'any? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(5) .faq-body', html: 'Sí. Al tancament de cada cicle el grup crea i presenta una mostra. En aquest nivell el material tendeix a ser més elaborat: escenes construïdes, composicions pròpies, presentacions obertes al públic. El procés de creació és part central del treball de l\'any, i l\'objectiu final és poder fer funcions en un teatre, amb el nostre cicle anomenat <em>La tirania del desig</em>.' }, { sel: '.faq-list .faq-item:nth-child(6) summary', html: 'Puc incorporar-me durant l\'any? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(6) .faq-body', html: 'Depèn del moment del cicle. En general es pot incorporar algú quan el grup no està en fase de creació avançada per a la mostra. Escriu-nos i t\'expliquem en quin punt estem i si té sentit que t\'incorporis ara o esperis a l\'inici del pròxim cicle.' }, { sel: '.faq-list .faq-item:nth-child(7) summary', html: 'Quant duren les classes? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(7) .faq-body', html: 'Cada trobada dura 3 hores, una vegada per setmana. És el temps mínim perquè el treball tingui profunditat real: escalfar-se, improvisar, reflexionar i tancar el cicle de la classe.' }, { sel: '.faq-list .faq-item:nth-child(8) summary', html: 'On es realitzen les classes? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(8) .faq-body', html: 'A l\'Espai La Mansió, Carrer de Roger de Flor 253, Local 2 i 3, al barri de Gràcia, Barcelona. Metro: Verdaguer (L5) o Sagrada Família (L2-L5).' }, { sel: '.cta-final-heading', html: 'Imaginar amb <br>el cos. <br><span class="acc">El cos com a territori.</span>' }, { sel: '.cta-final-sub', html: 'Una primera classe sense cost. Sense compromís.<br>Només per veure si és el teu lloc.' }, { sel: '.cta-nota', html: 'Incorporació per entrevista — Places limitades' }, { sel: '.info-h2', html: 'Tot el <br>que necessites <br>saber.' }, { sel: '.info-tagline', html: 'Una primera classe de prova sense cost. Sense compromisos. Per veure si el treball ressona amb el que busques.' }, { sel: 'a.btn-primary[href*="experiencia."]', html: 'Reservar plaça <span class="arrow">→</span>' }, { sel: '.testimonio-featured-text', html: 'Les classes amb Seba han estat una bogeria per a mi. Feia temps que volia sumar-me a un curs o taller de teatre i vaig trobar el millor lloc del món. És un espai lúdic on aprendràs a improvisar des del teu cos.' }, { sel: '.testimonio-featured-name', html: '★★★★★ · Fede L. · Alumne · Barcelona' }, { sel: '.testimonios-grid .testimonio-card:nth-child(1) .testimonio-text', html: 'Venia d\'una formació acadèmica i buscava alguna cosa que complementés la tècnica amb la recerca personal. Aquest taller fa exactament això: el treball és rigorós, però el punt d\'arribada és sempre alguna cosa teva.' }, { sel: '.testimonios-grid .testimonio-card:nth-child(1) .testimonio-name', html: 'Patricia V. · Actriu · Barcelona' }, { sel: '.testimonios-grid .testimonio-card:nth-child(2) .testimonio-text', html: 'El que més em va sorprendre va ser la qualitat de l\'escolta en el grup. Quan el nivell és similar el treball canvia completament. Cada classe obre alguna cosa que no hauries obert sol.' }, { sel: '.testimonios-grid .testimonio-card:nth-child(2) .testimonio-name', html: 'Iván P. · Actor independent · Barcelona' }, { sel: '.testimonios-grid .testimonio-card:nth-child(3) .testimonio-text', html: 'Havia fet diversos tallers i en molts el temps se n\'anava en explicar el bàsic. Aquí des del primer dia vam entrar directament al treball. Es nota que el nivell és diferent i això s\'agraeix moltíssim.' }, { sel: '.testimonios-grid .testimonio-card:nth-child(3) .testimonio-name', html: 'Elena G. · Estudiant d\'interpretació · Gràcia' }, { sel: '.testimonios-grid .testimonio-card:nth-child(4) .testimonio-text', html: 'No esperava trobar un espai on la poètica personal tingués tant de pes. No és un taller on t\'ensenyen a actuar: és un espai on aprens a reconèixer quin tipus d\'actor ets. Això no té preu.' }, { sel: '.testimonios-grid .testimonio-card:nth-child(4) .testimonio-name', html: 'Marta S. · Actriu i directora · Barcelona' }, { sel: '.galeria-titulo', html: 'El nostre univers, <br><span class="acc">les nostres imatges.</span>' }, { findText: 'p', from: 'Haz clic en cualquier foto para ampliarla.', to: 'Fes clic a qualsevol foto per ampliar-la.' }, ], '/avanzados/': [ { sel: '.video-h2', html: 'La tirania<br>del<br>desig.' }, { sel: '.video-body', html: 'Aquest espai proposa que els participants desenvolupin escenes pròpies i materials actorals per construir un cicle de funcions reals. Al llarg de l\'any investiguem situacions, vincles, imaginaris i conflictes fins a convertir-los en escenes vives capaces de sostenir-se davant el públic.', index: 1 }, { sel: '.video-body', html: 'L\'objectiu és entrenar actuant, però també travessar el procés complet de creació: assaig, reescriptura, muntatge i funció. Ja hem presentat funcions en espais com Badabadoc, dins del cicle <em>La tirania del desig</em>, compartint materials creats a l\'entrenament amb públic real i programació teatral.', index: 2 }, { sel: '.video-body', html: 'Direcció: <strong>Sebastián Mogordoy</strong> juntament amb <strong>Candelaria Sesin</strong><br>Espai La Mansió · Gràcia, Barcelona', index: 3 },  { sel: '.hero-tag', html: 'Taller 03 · Avançats' }, { sel: '.hero-title', html: 'El ser<br>mirat.' }, { sel: '.hero-subtitle', html: 'Laboratori d\'investigació tècnica i desenvolupament de la poètica. Entrenem actuar.' }, { sel: '.hero-tagline', html: 'Per a actors i estudiants avançats que volen investigar l\'actuació com a llenguatge, des de la improvisació dirigida.' }, { sel: '.intro-cta-line span', html: 'Incorporació per entrevista' }, { sel: '.info-section .overline', html: 'Informació pràctica' }, { findText: '.info-label', from: 'Nivel', to: 'Nivell' }, { findText: '.info-label', from: 'Horarios', to: 'Horaris' }, { findText: '.info-label', from: 'Lugar', to: 'Lloc' }, { findText: '.info-label', from: 'Precio', to: 'Preu' }, { findText: '.info-label', from: 'Coordinación', to: 'Coordinació' }, { sel: '.info-value', html: '<strong>Dimecres · 19 a 22 h.</strong><br><span class="info-note">Temporada 2026/27 · Inscripció oberta.</span>', index: 3 }, ], '/cuerpo-al-texto/': [ { sel: '.hero-tag', html: 'Taller d\'escena · Text · Veu' }, { sel: '.hero-title', html: 'Cos<br>al text.' }, { sel: '.hero-subtitle', html: 'Escenes, monòlegs i actuació des de la lògica viva de la situació.' }, { sel: '.hero-tagline', html: 'Entrenament per a actors i estudiants avançats que volen aprofundir el treball sobre la paraula, el conflicte, l\'escolta i la poètica escènica.' }, { sel: '.hero-dir-label', html: 'Estudi de teatre' }, { sel: '.hero-meta-item', html: '<strong>Barcelona · Gràcia</strong>', index: 0 }, { sel: '.hero-meta-item', html: 'Espai La Mansió', index: 1 }, { sel: '.hero-meta-item', html: 'Vacants limitades', index: 2 }, { sel: '.intro-section .overline', html: 'La idea central' }, { sel: '.intro-statement', html: 'Les paraules<br>surten d\'<br>un <span class="acc">cos.</span>' }, { sel: '.intro-pullquote p', html: 'El text<br>no es recita.' }, { sel: '.intro-cta-line span', html: 'Incorporació per entrevista' }, { sel: '.intro-p', html: 'El text no és literatura. No es «diu» ni s\'«interpreta». <strong>Apareix des d\'un estat</strong>, des de forces en joc, des de la lògica viva de la situació. El que el personatge diu no és el que l\'actor fa: l\'actor actua amb el text, no el text.', index: 0 }, { sel: '.intro-p', html: 'Aquest <strong>taller de teatre amb text</strong> treballa sobre escenes i monòlegs des de l\'actuació, no des de la lectura. El punt de partida és sempre la situació real: el vincle, el desig, la contradicció, el conflicte. La paraula arriba quan el cos ja és pres.', index: 1 }, { sel: '.intro-p', html: 'Treballem ritme, respiració, musicalitat i projecció no com exercicis tècnics aïllats, sinó com a conseqüència directa de l\'estat actoral. La veu no és un instrument separat: és actuació. El treball sobre <strong>monòlegs, escenes teatrals i tècnica actoral</strong> succeeix en relació, no en el buit.', index: 2 }, { sel: '.intro-break-text', html: 'Cada frase té<br>un cos.<br>La veu també actua.' }, { findText: '.intro-kw-tag', from: 'Escenas teatrales', to: 'Escenes teatrals' }, { findText: '.intro-kw-tag', from: 'Monólogos', to: 'Monòlegs' }, { findText: '.intro-kw-tag', from: 'Voz y actuación', to: 'Veu i actuació' }, { findText: '.intro-kw-tag', from: 'Técnica actoral', to: 'Tècnica actoral' }, { findText: '.intro-kw-tag', from: 'Barcelona · Gràcia', to: 'Barcelona · Gràcia' }, { sel: '.escena-section .overline', html: 'Entrenament' }, { sel: '.escena-h2', html: 'Què<br><span>entrenim.</span>' }, { sel: '.escena-intro', html: 'Cinc eixos que es treballen de forma integrada. No són mòduls separats: són dimensions d\'un mateix acte d\'actuar.' }, { sel: '.escena-concept', html: 'Escena', index: 0 }, { sel: '.escena-text', html: 'Anàlisi de situació, vincles, accions i forces en joc. L\'escena com a unitat de treball, no com a resultat.', index: 0 }, { sel: '.escena-concept', html: 'Text', index: 1 }, { sel: '.escena-text', html: 'Comprensió del text des de l\'escena i no des del literari. La partitura com a territori d\'acció, no com a guió.', index: 1 }, { sel: '.escena-concept', html: 'Veu', index: 2 }, { sel: '.escena-text', html: 'Ritme, respiració, musicalitat i projecció expressiva des de l\'estat actoral. La veu com extensió del cos a escena.', index: 2 }, { sel: '.escena-concept', html: 'Monòleg', index: 3 }, { sel: '.escena-text', html: 'Construcció de presència, pensament viu i escolta interna. El monòleg com escena, no com recitació.', index: 3 }, { sel: '.escena-concept', html: 'Poètica', index: 4 }, { sel: '.escena-text', html: 'Recerca d\'una forma pròpia d\'actuar i dir. La interpretació teatral com a llenguatge personal, no com a imitació d\'un model.', index: 4 }, { sel: '.video-section .overline', html: 'El treball en vídeo' }, { sel: '.video-h2', html: 'Dir<br>des de<br>la <span class="acc">escena.</span>' }, { sel: '.video-body', html: 'El treball sobre improvisació en escenes escrites: com el text s\'obre quan l\'actor l\'habita des de l\'interior de la situació i no des de fora, interpretant-lo. L\'actuació no il·lustrativa. El <strong>ritme com a força</strong>, l\'escolta com acció, la ressonància del conflicte real.', index: 0 }, { sel: '.video-body', html: 'Una classe és un espai d\'investigació: es treballa sobre el material, s\'atura, es repeteix, es transforma. No hi ha performació. Hi ha <strong>procés tècnic i poètic al mateix temps.</strong>', index: 1 }, { sel: '.video-coord', html: 'Coordinació: Sebastián Mogordoy' }, { sel: '.testimonios-section .overline', html: 'El que diuen' }, { sel: '.testimonios-h2', html: 'Van entrenar<br>amb nosaltres.' }, { sel: '.carousel-h2', html: 'En <span>moviment.</span>' }, { sel: '.info-section .overline', html: 'Informació pràctica' }, { sel: '.info-h2', html: 'Tot el <br>que necessites <br>saber.' }, { sel: '.info-tagline', html: 'Incorporació per entrevista o experiència prèvia. Vacants molt limitades. Si t\'interessa, escriu-nos com abans millor.' }, { findText: '.info-label', from: 'Nivel', to: 'Nivell' }, { findText: '.info-label', from: 'Modalidad', to: 'Modalitat' }, { findText: '.info-label', from: 'Formato', to: 'Format' }, { findText: '.info-label', from: 'Horarios', to: 'Horaris' }, { findText: '.info-label', from: 'Lugar', to: 'Lloc' }, { findText: '.info-label', from: 'Incorporación', to: 'Incorporació' }, { findText: '.info-label', from: 'Precio', to: 'Preu' }, { findText: '.info-label', from: 'Coordinación', to: 'Coordinació' }, { sel: '.info-value', html: 'Avançat — actors, estudiants amb trajectòria escènica, formació actoral prèvia.', index: 0 }, { sel: '.info-value', html: '<strong>Escenes i monòlegs.</strong> Treball sobre text dramàtic des de l\'actuació.', index: 1 }, { sel: '.info-value', html: '<strong>Una vegada per setmana · 3 hores per trobada.</strong> Cicle anual amb mostra.', index: 2 }, { sel: '.info-value', html: '<strong>Dilluns · 19 a 22 h.</strong><br><span class="info-note">Temporada 2026/27 · Inscripció oberta.</span>', index: 3 }, { sel: '.info-value', html: '<strong>Espai La Mansió</strong> · Carrer de Roger de Flor, 253, Local 2 i 3 · Gràcia, Barcelona.<br>Metro: Verdaguer o Sagrada Família.', index: 4 }, { sel: '.info-value', html: 'Per entrevista o experiència prèvia. <strong>Vacants molt limitades.</strong>', index: 5 }, { sel: '.info-value', html: '100 €/mes · Sense matrícula. <strong>Classe de prova sense cost.</strong><br><span class="info-note">Si no arribes a pagar el total, escriu-nos i t\'expliquem les opcions de beques i mitges beques.</span>', index: 6 }, { sel: '.info-value', html: 'Sebastián Mogordoy', index: 7 }, { sel: '.ubicacion-section .overline', html: 'On trobar-nos' }, { sel: '.ubicacion-h2', html: 'Gràcia,<br>Barcelona.' }, { sel: '.faq-section .overline', html: 'Preguntes freqüents' }, { sel: '.faq-h2', html: 'Preguntes<br>freqüents.' }, { sel: '.faq-list .faq-item:nth-child(1) summary', html: 'Necessito experiència prèvia per a aquest taller de teatre amb text? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(1) .faq-body', html: 'Sí. Aquest taller està pensat per a persones que ja tenen recorregut escènic: actors de formació acadèmica, estudiants avançats, persones amb experiència en altres tallers o en teatre independent. No és un espai per començar des de zero. Si estàs començant, pots veure el <a href="/principiantes/" style="color:var(--accent);">taller de principiants</a>.' }, { sel: '.faq-list .faq-item:nth-child(2) summary', html: 'Es treballen monòlegs? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(2) .faq-body', html: 'Sí. El monòleg és una de les formes centrals del treball. No com exercici de memorització sinó com a construcció de presència, pensament viu i escolta interna. Treballem el monòleg com escena — amb un interlocutor real o imaginari, amb forces, amb estat actoral.' }, { sel: '.faq-list .faq-item:nth-child(3) summary', html: 'Puc portar els meus propis textos o escenes? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(3) .faq-body', html: 'Sí. Pots portar textos que t\'interessin — clàssics, contemporanis, fragments, materials propis — i treballar-los des de la lògica de la situació i de les forces en joc. El criteri no és el gènere ni l\'època sinó les possibilitats de treball actoral que ofereix.' }, { sel: '.faq-list .faq-item:nth-child(4) summary', html: 'Quin tipus d\'escenes es treballen? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(4) .faq-body', html: 'Escenes de dues o més persones, monòlegs, fragments d\'obres, material de creació pròpia. El criteri no és el gènere: són situacions amb conflicte real, vincles, desig, contradicció. No treballem escenes de manera il·lustrativa. El treball és sempre des de dins de la situació.' }, { sel: '.faq-list .faq-item:nth-child(5) summary', html: 'Es treballa tècnica vocal? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(5) .faq-body', html: 'Sí, però la veu no es treballa com un aparell separat del cos. Treballem ritme, respiració, musicalitat, projecció i ressonància en relació directa amb l\'estat actoral i la lògica de l\'escena. La veu és també actuació.' }, { sel: '.faq-list .faq-item:nth-child(6) summary', html: 'Hi ha mostra o funció al final de l\'any? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(6) .faq-body', html: 'Sí. Al tancament de cada cicle el grup presenta una mostra de treball. En aquest taller el material sol ser d\'una major elaboració: escenes acabades, monòlegs treballats, composicions pròpies. El procés de creació és part integral de l\'any, no un apèndix final.' }, { sel: '.faq-list .faq-item:nth-child(7) summary', html: 'És un taller d\'anàlisi de text? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(7) .faq-body', html: 'No. El text no s\'estudia com a literatura. Es treballa com partitura d\'acció, com territori de forces, com material viu. L\'anàlisi — si n\'hi ha — sempre està al servei del fer: d\'estar a escena, d\'actuar. No és un seminari, és un laboratori.' }, { sel: '.faq-list .faq-item:nth-child(8) summary', html: 'Puc incorporar-me durant l\'any? <span class="faq-arrow" aria-hidden="true">+</span>' }, { sel: '.faq-list .faq-item:nth-child(8) .faq-body', html: 'Depèn del moment del cicle i de la teva experiència prèvia. La incorporació és per entrevista. Escriu-nos i avaluem junts si el moment i el nivell de treball són els adequats perquè t\'incorporis ara o en el pròxim cicle.' }, { sel: '.cta-final-heading', html: 'Habitar <br><span class="acc">les paraules.</span>' }, { sel: '.cta-final-sub', html: 'Incorporació per entrevista o experiència prèvia.<br>Escriu-nos i ho parlem.' }, { sel: '.cta-nota', html: 'Incorporació per entrevista — Places limitades' }, { sel: '.editorial-strip-caption span', html: 'Cos al text' }, { sel: '.editorial-strip-caption p', html: 'La paraula<br>com a esdeveniment<br>físic.' }, { sel: 'a.btn-primary[href*="Cuerpo"]', html: 'Consultar vacants <span class="arrow">→</span>' }, { sel: '.testimonio-featured .testimonio-text', html: 'Feia anys treballant amb text i sentia que alguna cosa no tancava. Deia bé, em movia bé, però no hi havia res viu a dins. En aquest taller vaig entendre que no és qüestió de dir millor: és qüestió d\'estar en situació. La diferència entre recitar i actuar la vaig entendre aquí per primera vegada.' }, { sel: '.testimonio-featured .testimonio-author', html: 'Marta F. — Actriu, formació ESAD' }, { sel: '.testimonio-grid .testimonio-item:nth-child(1) .testimonio-text', html: 'El treball amb la veu em va obrir alguna cosa que no esperava. No era tècnica vocal separada de l\'actuació, era tot junt. Quan l\'estat és real, la veu sona diferent. Això no ho havia escoltat en cap altre lloc.' }, { sel: '.testimonio-grid .testimonio-item:nth-child(1) .testimonio-author', html: 'Daniel V. — Actor de companyia' }, { sel: '.testimonio-grid .testimonio-item:nth-child(2) .testimonio-text', html: 'Vaig treballar monòlegs durant anys sense entendre què em bloquejava. Aquí vaig descobrir que el problema era que els tractava com textos. Des que els treballo com escenes, amb algú real o imaginari davant, alguna cosa es va obrir.' }, { sel: '.testimonio-grid .testimonio-item:nth-child(2) .testimonio-author', html: 'Andrea P. — Estudiant avançada' }, { sel: '.testimonio-grid .testimonio-item:nth-child(3) .testimonio-text', html: 'El que més em va sorprendre va ser la precisió. No és un taller on tot val. Es treballa amb molta atenció sobre el que passa realment a escena. Això és exactament el que necessitava.' }, { sel: '.testimonio-grid .testimonio-item:nth-child(3) .testimonio-author', html: 'Javier C. — Actor independent, Barcelona' }, { sel: '.testimonio-grid .testimonio-item:nth-child(4) .testimonio-text', html: 'El ritme del text va començar a tenir sentit quan el vaig connectar amb la respiració i amb el que vull a l\'escena. Abans era decoratiu. Ara és constitutiu. Aquesta diferència la vaig aprendre aquí.' }, { sel: '.testimonio-grid .testimonio-item:nth-child(4) .testimonio-author', html: 'Lucía M. — Actriu i directora' }, ], '/quienes-somos/': [ { sel: '.hero-overline', html: 'Tallers de Teatre a Barcelona · Des del 2010' }, { sel: '.hero-tagline', html: 'Quinze anys investigant l\'actuació,<br>el cos, la improvisació<br>i l\'escena.' }, { sel: '.hero-cta-row a.btn-primary:not(.btn-wa)', html: 'Veure tallers <span class="arrow">→</span>' }, { sel: '.manifiesto-section .overline', html: 'La nostra mirada' }, { sel: '.manifiesto-left h2', html: 'El teatre que ens interessa fractura el real.<span class="acc"> Altera el quotidià.</span>' }, { sel: '.manifiesto-p', html: 'Proposa intensitats poètiques que ens fan alliberar la representació «del personatge que som a la vida» per llençar-nos en un no saber que ens obre a altres possibilitats d\'existència.' }, { sel: '.editorial-full-text h2', html: 'Tenim <br><span class="acc">el teatre.</span>' }, { sel: '.editorial-full-text p', html: 'En un món on la realitat ens empeny a sobreviure enmig de diferents guerres, el teatre continua sent la nostra trinxera, el nostre refugi, lloc d\'expressió, experimentació i investigació, del humà i del procés creatiu.', index: 0 }, { sel: '.editorial-full-text p', html: 'Quan la vida es posa una mica avorrida o massa agressiva, el teatre ens proposa intensitats poètiques i expressives que ens fan alliberar la representació «del personatge que som a la vida» per llençar-nos en un no saber que ens obre a altres possibilitats d\'existència. Ens convida a ser tot allò que no som.', index: 1 }, { sel: '#sebastian .persona-role', html: 'Actor · Director · Professor' }, { sel: '#sebastian .pullquote p', html: 'L\'actuació neix de l\'acte.' }, { sel: '#sebastian .persona-bio p', html: 'Actor, director i professor de teatre argentí establert a Barcelona. Format al costat de <strong>Ricardo Bartís</strong> al Sportivo Teatral de Buenos Aires, referència ineludible del teatre argentí contemporani. Els seus quinze anys de docència a Buenos Aires i Barcelona han construït un mètode de treball reconegut per la comunitat teatral.', index: 0 }, { sel: '#sebastian .persona-bio p', html: 'Actualment forma part de l\'elenc protagonista d\'<em>El Fill</em>, de Jon Fosse, dirigida per <strong>Ferran Utzet</strong>, estrenada al <strong>Teatre Lliure</strong> de Barcelona. Va protagonitzar <em>Eufòria i Desassossec</em>, de Sergio Boris, amb temporada al Festival Temporada Alta 2024, la <strong>Sala Beckett</strong> i els <strong>Teatros del Canal</strong> de Madrid. Al cinema, va formar part de la pel·lícula <em>El profesor</em>, producció de Netflix.', index: 1 }, { sel: '#sebastian .persona-bio p', html: 'El seu treball actoral ha estat descrit com «d\'un altre planeta» (elDiario.es). Dirigeix els cursos de Principiants, Intermedis, Avançats i Cos al text a Gràcia, Barcelona.', index: 2 }, { sel: '#sebastian .cv-accordion summary', html: 'Llegir el CV complet' }, { sel: '#candelaria .persona-role', html: 'Actriu · Directora · Docent' }, { sel: '#candelaria .pullquote p', html: 'El teatre com espai de construcció col·lectiva.' }, { sel: '#candelaria .persona-bio p', html: 'Actriu, directora, gestora cultural i docent de teatre. Formada a Buenos Aires, on va desenvolupar una trajectòria intensa al teatre independent com creadora i pedagoga. Establerta a Barcelona des del 2020, on codirigeix els tallers amb Sebastián Mogordoy.', index: 0 }, { sel: '#candelaria .persona-bio p', html: 'Va coordinar les activitats del teatre <strong>Silencio de Negras</strong> i va crear amb diversos grups diferents cicles de teatre independent: <em>Enredadera</em> a la llibreria La Libre, <em>Derrapé</em> a Sala de Màquines, <em>Circuito Lumínico</em> i <em>Lo que dura una canción</em>. Docent de teatre a Buenos Aires i Barcelona des de fa més d\'una dècada.', index: 1 }, { sel: '#candelaria .persona-bio p', html: 'La seva mirada pedagògica posa el focus en l\'<strong>escolta grupal</strong>, l\'espai com a territori de creació, i el desenvolupament de l\'expressivitat individual dins del col·lectiu. Amb ella el treball té cos, humor i una presència particular que fa del grup una banda.', index: 2 }, { sel: '#candelaria .cv-accordion summary', html: 'Llegir tot el CV complet' }, { sel: '.asistentes-overline', html: 'Assistents d\'entrenament' }, { sel: '.asistentes-h2', html: 'Acompanyen<br>el procés.' }, { sel: '.asistente-card:first-child .asistente-role', html: 'Actriu · Ballarina · Docent' }, { sel: '.asistente-card:nth-child(2) .asistente-role', html: 'Actor · Docent' }, { sel: '.asistente-summary', html: 'Veure CV <span class="asistente-arrow">▾</span>' }, { sel: '.comunidad-section .overline, .banda-header .overline', html: 'Des del 2010' }, { sel: '.banda-title', html: 'La banda <br>dels <br><span class="acc">actors.</span>' }, { sel: '.banda-subtitle', html: 'aquella banda mil·lenària' }, { sel: '.banda-p', html: 'Vam começar l\'any 2010 amb un petit grup al Camarín de las Musas, a Buenos Aires. <strong>Avui continuem fent i pensant el teatre que ens agrada des de Barcelona.</strong>', index: 0 }, { sel: '.banda-p', html: 'Més que una escola, construïm un nosaltres d\'actors, estudiants i persones que busquen una altra intensitat en la trobada amb l\'escena. Barcelona és una ciutat vibrant, plena de persones de diverses edats, costums i nacionalitats. Cultivem un espai de creació, trobada real, expressió i construcció social.', index: 1 }, { findText: '.espacio-dato-label', from: 'Dónde', to: 'On' }, { findText: '.espacio-dato-label', from: 'Clases', to: 'Classes' }, { sel: '.galeria-section .overline', html: 'L\'univers' }, { sel: '.galeria-titulo', html: 'El nostre univers <br><span class="acc">en imatges.</span>' }, { sel: '.galeria-sub', html: '15 anys de classes, entrenaments, funcions i processos.' }, { sel: '.cta-final-heading', html: 'Ser el <br>poema. <br><span class="acc">Imaginar amb el cos.</span>' }, { sel: '.cta-final-sub', html: 'Un espai per actuar,<br>pensar, imaginar<br>i estar amb altres.' }, { sel: '.hero-seo-h1', html: 'Professors de teatre Barcelona · Sebastián Mogordoy' }, { sel: '.hero-mobile-names-years', html: '15 anys de teatre' }, { sel: '.hero-mobile-names-text', html: 'Sebastián Mogordoy' }, { sel: '.asistente-bio', html: 'Actriu i ballarina portenya, llicenciada per la UNA. Integra moviment, dansa i actuació com a llenguatges indissociables. Assistent als tallers des de 2024.', index: 0 }, { sel: '.asistente-bio', html: 'Actor i docent, Llicenciat en Arts Dramàtiques (UNA). Formulat en el teatre argentí contemporani. Assistent als tallers des de 2024.', index: 1 }, ], '/contacto/': [ { findText: '.overline', from: 'Talleres de Teatro Barcelona · Desde 2010', to: 'Tallers de Teatre Barcelona · Des del 2010' }, { sel: '.contact-hero-title', html: 'Vine a una classe <br /> de prova, <br><span>¡sense cost!</span>' }, { sel: '.contact-hero-sub', html: 'Escriu-nos, explica\'ns en quin nivell estàs i et diem com provar-ho.' }, { findText: '.quick-strip-label', from: 'Contacto', to: 'Contacte' }, { findText: '.overline', from: 'Escríbenos', to: 'Escriu-nos' }, { sel: '.form-heading', html: 'Reserva el teu lloc.' }, { sel: '.form-sub', html: 'Et responem en menys de 24 hores amb tota la info per començar.' }, { sel: 'label[for="nombre"]', html: 'Nom' }, { sel: 'input[name="nombre"]', attr: 'placeholder', val: 'El teu nom' }, { sel: 'label[for="apellido"]', html: 'Cognom' }, { sel: 'input[name="apellido"]',attr: 'placeholder', val: 'El teu cognom' }, { sel: 'label[for="email"]', html: 'Correu electrònic' }, { sel: 'input[name="email"]', attr: 'placeholder', val: 'tu@correu.com' }, { sel: 'label[for="telefono"]', html: 'Telèfon / WhatsApp' }, { sel: 'label[for="nivel"]', html: 'Quin taller t\'interessa?' }, { sel: 'option[value=""]', html: 'Selecciona un taller' }, { sel: 'option[value="principiantes"]', html: 'Principiants — sense experiència prèvia' }, { sel: 'option[value="intermedios"]', html: 'Intermedis — amb recorregut teatral' }, { sel: 'option[value="avanzados"]', html: 'Avançats — El ser mirat, laboratori' }, { sel: 'option[value="cuerpo-al-texto"]', html: 'Cos al text — actors amb formació' }, { sel: 'option[value="no-se"]', html: 'Encara no ho sé, necessito orientar-me' }, { sel: 'label[for="mensaje"]', html: 'Missatge (opcional)' }, { sel: 'textarea[name="mensaje"]', attr: 'placeholder', val: 'Explica\'ns alguna cosa sobre tu, la teva experiència o el que busques…' }, { sel: '.form-privacy', html: 'En enviar aquest formulari acceptes que les teves dades s\'usin únicament per respondre la teva consulta. No compartim informació amb tercers.' }, { sel: 'button[type="submit"]', html: 'Enviar missatge <span style="margin-left:4px;">→</span>' }, { sel: '.form-success h3', html: 'Missatge enviat!' }, { sel: '.form-success p', html: 'Et responem en menys de 24 hores. Mentrestant, pots escriure\'ns per WhatsApp si ho necessites.' }, { sel: '.info-block-title', html: 'Contacte', index: 0 }, { sel: '.info-block-title', html: 'Xarxes socials', index: 1 }, { sel: '.contact-card-note', html: 'La manera més ràpida de contactar-nos', index: 0 }, { sel: '.contact-card-note', html: 'Et responem en menys de 24h', index: 1 }, { findText: '.footer-copy', from: '© 2025 Talleres de Teatro Barcelona · talleresdeteatro.es', to: '© 2025 Tallers de Teatre Barcelona · talleresdeteatro.es' }, { findText: '.footer-copy', from: 'Espacio La Mansión · Gràcia, Barcelona', to: 'Espai La Mansió · Gràcia, Barcelona' }, ], '/info/': [ { sel: 'h1', html: 'Informació, horaris <br /> i preus 2026/27' }, ], '/blog/': [ { sel: '.blog-header .overline', html: 'Articles sobre actuació, improvisació i entrenament' }, { sel: '.blog-title', html: 'Pensem <br><span>el teatre.</span>' }, { sel: '.blog-subtitle', html: 'Articles sobre teatre, actuació i improvisació. Per Sebastián Mogordoy.' }, { sel: 'span.blog-tab', html: 'Lectures' }, { sel: 'a.blog-tab.tab-quiz', html: 'Qüestionari' }, { findText: '.card-tag', from: 'Técnica actoral', to: 'Tècnica actoral' }, { findText: '.card-tag', from: 'Filosofía del teatro', to: 'Filosofia del teatre' }, { findText: '.card-tag', from: 'Entrenamiento', to: 'Entrenament' }, { findText: '.card-tag', from: 'Metodología', to: 'Metodologia' }, { findText: '.card-tag', from: 'Escena y situación', to: 'Escena i situació' }, { findText: '.card-tag', from: 'Maestros', to: 'Mestres' }, { findText: '.card-tag', from: 'Proceso creativo', to: 'Procés creatiu' }, { sel: '.card-title', html: 'Per què actuar <br /> no és representar', index: 0 }, { sel: '.card-title', html: 'El joc <br /> com a origen', index: 1 }, { sel: '.card-title', html: 'Imaginar <br /> vs. pensar', index: 2 }, { sel: '.card-title', html: 'Què és la <br /> improvisació dirigida', index: 3 }, { sel: '.card-title', html: 'El voler <br /> animal', index: 4 }, { sel: '.card-title', html: 'Entre dos <br /> focs', index: 5 }, { sel: '.card-title', html: 'El cos <br /> com a territori', index: 6 }, { sel: '.card-title', html: 'La mirada <br /> és un acte', index: 7 }, { sel: '.card-title', html: 'El cos <br /> parla primer', index: 8 }, { sel: '.card-title', html: 'El que no <br /> es pot dir', index: 9 }, { sel: '.card-title', html: 'L\'espera <br /> activa', index: 10 }, { sel: '.card-title', html: 'Som <br /> una imatge', index: 11 }, { sel: '.card-title', html: 'El teu univers <br /> no és la teva biografia', index: 12 }, { sel: '.card-title', html: 'Habitar <br /> el present', index: 13 }, { sel: '.card-title', html: 'El vèrtig <br /> de la pàgina en blanc', index: 14 }, { sel: '.card-title', html: 'Cossos <br /> desitjants', index: 15 }, { sel: '.card-title', html: 'El poder <br /> del vestuari', index: 16 }, { sel: '.card-title', html: 'L\'assaig', index: 17 }, { sel: '.card-excerpt', html: 'La diferència entre «fer com si» i estar de veritat a escena. El «personatget» i el salt al present que ho canvia tot.', index: 0 }, { sel: '.card-excerpt', html: 'De la infància a l\'escenari: per què actuar és un superjoc adult, apassionat i sense ingenuïtat ni solemnitat.', index: 1 }, { sel: '.card-excerpt', html: 'Pensar organitza. Imaginar encarna. La diferència més important que existeix per a un actor, i com entrenar-la.', index: 2 }, { sel: '.card-excerpt', html: 'L\'eix de la nostra filosofia d\'entrenament: crear sense guió, des del cos, amb desig i sense representar.', index: 3 }, { sel: '.card-excerpt', html: 'Com habitar una situació a escena i deixar d\'explicar el personatge. La força que ho canvia tot.', index: 4 }, { sel: '.card-excerpt', html: 'Raúl Serrano i Ricardo Bartís: com dues visions de vegades oposades van forjar una mirada pròpia sobre el teatre.', index: 5 }, { sel: '.card-excerpt', html: 'El cos no representa: habita. L\'espai escènic com a camp d\'acció i l\'actor com a territori viu.', index: 6 }, { sel: '.card-excerpt', html: 'En teatre, mirar no és observar passivament. És prendre poder, investigar l\'altre, deixar-se travessar.', index: 7 }, { sel: '.card-excerpt', html: 'Abans que arribin les paraules, el cos ja va parlar. Per què el moviment és el primer text de l\'actor.', index: 8 }, { sel: '.card-excerpt', html: 'El teatre com a espai on el prohibit troba veu. El desig reprimit com a motor de tota acció dramàtica.', index: 9 }, { sel: '.card-excerpt', html: 'Esperar a escena no és no fer res. L\'escolta real és una de les accions més exigents del treball actoral.', index: 10 }, { sel: '.card-excerpt', html: 'Abans de dir la primera paraula, ja estàs narrant. El cos a l\'espai és una imatge viva que interpel·la qui l\'observa.', index: 11 }, { sel: '.card-excerpt', html: 'El teatre no és psicodrama. No ens interessa la teva història privada, ens interessa el teu univers personal: la teva sensibilitat, els teus ritmes, les teves imatges.', index: 12 }, { sel: '.card-excerpt', html: 'El personatget apareix quan actuem per explicar una idea. L\'alternativa és el voler animal: un desig que ancora el cos en temps real.', index: 13 }, { sel: '.card-excerpt', html: 'Què passa si em bloquejo? El vèrtig apareix quan busquem lògica en la improvisació. La sortida és baixar al cos i deixar que les paraules siguin imatges.', index: 14 }, { sel: '.card-excerpt', html: 'La societat genera un cos domesticat que reprimeix l\'impuls. Al taller donem la batalla contrària: despertar la desmesura i la fricció viva.', index: 15 }, { sel: '.card-excerpt', html: 'Posar-se una peça no és disfressar-se. El vestuari modifica la corporalitat, altera el centre de gravetat i canvia tot el que narrem abans de parlar.', index: 16 }, { sel: '.card-excerpt', html: 'L\'assaig no és un espai per a la correcció ni l\'obediència. És el territori de major perill i fricció, on el cos intenta obrir aquella esquerda en la realitat.', index: 17 }, { findText: '.card-cta', from: 'Leer artículo', to: 'Llegir article' }, { sel: '.blog-cta-text h2', html: '¿Vols viure\'l<br>a escena?' }, { sel: '.blog-cta-text p', html: 'La primera classe és gratuïta. Vine a provar l\'entrenament i descobreix si el teatre és el teu lloc.' }, { sel: '.blog-cta .btn-primary', html: 'Primera classe gratuïta →' }, { sel: '.footer-links a[href="/principiantes/"]', html: 'Principiants' }, { sel: '.footer-links a[href="/intermedios/"]', html: 'Intermedis' }, { sel: '.footer-links a[href="/avanzados/"]', html: 'Avançats' }, { sel: '.footer-links a[href="/cuerpo-al-texto/"]', html: 'Cos al text' }, { sel: '.footer-links a[href="/contacto/"]', html: 'Contacte' }, { findText: '.footer-copy', from: '© 2026 Talleres de Teatro Barcelona · Gràcia', to: '© 2026 Tallers de Teatre Barcelona · Gràcia' }, ], '/blog/articulo/': [ { sel: '.breadcrumb a[href="/"]', html: 'Inici' }, { sel: '.breadcrumb a[href="/blog/"]', html: 'Lectures' }, { findText: '.meta-author', from: 'Por Sebastián Mogordoy', to: 'Per Sebastián Mogordoy' }, { sel: '.articles-nav-title', html: 'Més articles' }, { findText: '.mq-eyebrow', from: 'Cuestionario', to: 'Qüestionari' }, { sel: '.mq-title', html: '¿Ho tens<br>clar?' }, { findText: '.mq-subtitle', from: '3 preguntas sobre lo que acabas de leer.', to: '3 preguntes sobre el que acabes de llegir.' }, { sel: '.mq-cta-btn', html: 'Explorar tots els qüestionaris →' }, { sel: '.footer-links a[href="/principiantes/"]', html: 'Principiants' }, { sel: '.footer-links a[href="/intermedios/"]', html: 'Amb experiència' }, { sel: '.footer-links a[href="/contacto/"]', html: 'Contacte' }, { sel: '.footer-links a[href="/blog/"]', html: 'Lectures' }, { findText: '.footer-copy', from: '© 2026 Talleres de Teatro Barcelona · Gràcia', to: '© 2026 Tallers de Teatre Barcelona · Gràcia' }, ], '/cuestionario/': [ { sel: '.nav-back', html: '← Lectures' }, { findText: '.landing-eyebrow', from: 'Talleres de Teatro · Barcelona', to: 'Tallers de Teatre · Barcelona' }, { sel: '.landing-title', html: 'TEATRE<br><em>QÜESTIONARI</em>' }, { findText: '.landing-desc', from: 'Elige un tema y pon a prueba lo que sabes.', to: 'Tria un tema i posa a prova el que saps.' }, { findText: '.landing-count', from: '9 temas · 4 preguntas cada uno', to: '9 temes · 4 preguntes cadascun' }, { sel: '#quiz-back-btn', html: '← Temes' }, { findText: '#q-counter, .q-counter', from: 'Pregunta', to: 'Pregunta' }, { findText: '#hint-btn, .hint-btn', from: '▸ PISTA', to: '▸ PISTA' }, ], }; function applyList(list) { list.forEach(function (item) { try { if (item.findText) { document.querySelectorAll(item.findText).forEach(function (el) { if (el.textContent.trim() === item.from) el.textContent = item.to; }); return; } var els = Array.from(document.querySelectorAll(item.sel)); if (item.index !== undefined) els = els[item.index] ? [els[item.index]] : []; els.forEach(function (el) { if (item.attr) { el.setAttribute(item.attr, item.val); } else if (item.html !== undefined) { el.innerHTML = item.html; } }); } catch (e) { } }); } function apply(lang) { if (lang === 'es') { localStorage.setItem('ttb_lang', 'es'); location.reload(); return; } applyList(COMMON); var path = location.pathname; if (path !== '/' && path.slice(-1) !== '/') path += '/'; if (PAGES[path]) applyList(PAGES[path]); if (path.startsWith('/blog/') && path !== '/blog/') { applyList(PAGES['/blog/articulo/']); } document.querySelectorAll('[data-ca]').forEach(function(el) { el.innerHTML = el.getAttribute('data-ca'); }); document.documentElement.lang = 'ca'; localStorage.setItem('ttb_lang', 'ca'); updateToggle('ca'); } function updateToggle(lang) { document.querySelectorAll('.lang-toggle').forEach(function (btn) { if (lang === 'ca') { btn.textContent = 'ES'; btn.setAttribute('data-target', 'es'); btn.setAttribute('aria-label', 'Canviar a castellà'); btn.classList.add('lang-active'); } else { btn.textContent = 'CA'; btn.setAttribute('data-target', 'ca'); btn.setAttribute('aria-label', 'Canviar a català'); btn.classList.remove('lang-active'); } }); } document.addEventListener('DOMContentLoaded', function () { document.querySelectorAll('.lang-toggle').forEach(function (btn) { btn.addEventListener('click', function () { var target = this.getAttribute('data-target') || 'ca'; apply(target); }); }); var saved = localStorage.getItem('ttb_lang'); if (saved === 'ca') apply('ca'); }); window.TTBLang = { apply: apply }; })();